def evaluate(self, flat_route):
    """
    Compute total distance of a flat route (sequence of node indices, typically
    including depot zeros). Returns a float.

    Improvements:
    - Accepts any iterable (lists, tuples, numpy arrays, generators).
    - Uses numpy vectorized indexing for long routes when the distance matrix is
      a 2D numpy ndarray and indices are in range.
    - Falls back to a robust Python loop for other distance_matrix types
      (including callables, lists of lists, scipy sparse row accessors, etc.).
    - Provides clearer error messages for common issues (bad indices, non-int
      route entries, non-numeric distances).
    - Uses math.fsum for improved floating-point accumulation on long routes.
    """
    import math
    try:
        import numpy as np  # optional; used only if available
    except Exception:
        np = None

    # Normalize input without unnecessary allocations
    try:
        n = len(flat_route)
        seq = flat_route
    except TypeError:
        seq = list(flat_route)
        n = len(seq)

    if n <= 1:
        return 0.0

    dm = self.distance_matrix
    VECTORIZE_THRESHOLD = 128  # route length threshold to prefer vectorized path

    # Attempt fast vectorized path when dm is a 2D numpy array and numpy is present
    if np is not None and isinstance(dm, np.ndarray) and dm.ndim == 2 and n >= VECTORIZE_THRESHOLD:
        try:
            idx = np.asarray(seq, dtype=np.intp)
            if idx.size != n:
                idx = idx.ravel()
            # Validate indices to avoid unintended negative/wrap-around indexing
            if idx.min() < 0 or idx.max() >= dm.shape[0]:
                raise IndexError(f"Route contains out-of-bounds index (min={int(idx.min())}, max={int(idx.max())}, dm.shape={dm.shape}).")
            # pairwise distances
            pairwise = dm[idx[:-1], idx[1:]]
            return float(pairwise.sum())
        except Exception:
            # Fall back to safe loop on any problem (preserve original functionality)
            pass

    # Fallback loop: works with callables and other distance matrix types
    it = iter(seq)
    try:
        first = next(it)
    except StopIteration:
        return 0.0

    # Convert first index to int (produce helpful error on failure)
    try:
        prev = int(first)
    except Exception as e:
        raise TypeError(f"Route indices must be integers (first element: {first!r}).") from e

    # Decide accumulation strategy: use math.fsum for long routes to reduce rounding error
    use_fsum = n > 256
    if use_fsum:
        parts = []
    total = 0.0
    dm_callable = callable(dm)

    for node in it:
        try:
            cur = int(node)
        except Exception as e:
            raise TypeError(f"Route indices must be integers (got {node!r}).") from e

        try:
            if dm_callable:
                dist = dm(prev, cur)
            else:
                dist = dm[prev, cur]
        except Exception as e:
            # Provide contextual information about failing pair access
            raise IndexError(f"Error accessing distance for pair ({prev}, {cur}): {e}") from e

        try:
            fdist = float(dist)
        except Exception as e:
            raise TypeError(f"Distance value for pair ({prev}, {cur}) is not numeric: {dist!r}") from e

        if use_fsum:
            parts.append(fdist)
        else:
            total += fdist

        prev = cur

    if use_fsum:
        return float(math.fsum(parts))
    return float(total)
